      en: ["Took 11 years to complete.", "The interior is decorated with glass and ceramic mosaics.", "Located on a steep hill outside of Huế."],
      es: ["La construcción tomó 11 años en completarse.", "El interior está decorado con mosaicos de vidrio y cerámica.", "Se encuentra en una colina empinada a las afueras de Huế."],
