      hu: ["Amerikai katonai járműveket és fegyvereket tartalmaz.", "Dokumentálja a háború borzalmait.", "A város egyik legnépszerűbb látványossága."],
      ro: ["Conține vehicule și armament militar american.", "Documentează atrocitățile războiului.", "Una dintre cele mai populare atracții ale orașului."],
